[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    /* ============================================
       DESIGN SYSTEM — Global Aid Alliance
       Colors in OKLCH for perceptual uniformity
    ============================================ */
    :root {
      /* Brand palette */
      --red-primary: oklch(50% 0.18 18);
      --red-dark: oklch(40% 0.18 18);
      --red-light: oklch(62% 0.18 18);
      --red-surface: oklch(96% 0.03 18);
      --navy: oklch(30% 0.08 245);
      --navy-light: oklch(40% 0.08 245);
      --navy-surface: oklch(95% 0.02 245);

      /* Neutrals */
      --white: oklch(100% 0 0);
      --gray-50: oklch(98% 0.005 245);
      --gray-100: oklch(96% 0.005 245);
      --gray-200: oklch(92% 0.005 245);
      --gray-300: oklch(85% 0.01 245);
      --gray-400: oklch(70% 0.01 245);
      --gray-500: oklch(55% 0.01 245);
      --gray-600: oklch(40% 0.015 245);
      --gray-700: oklch(30% 0.015 245);
      --gray-800: oklch(22% 0.02 245);
      --gray-900: oklch(15% 0.02 245);

      /* Semantic */
      --text-primary: var(--gray-900);
      --text-secondary: var(--gray-600);
      --text-muted: var(--gray-400);
      --bg-primary: var(--white);
      --bg-surface: var(--gray-50);
      --bg-muted: var(--gray-100);
      --border-color: var(--gray-200);
      --border-strong: var(--gray-300);

      /* Spacing scale (4px base) */
      --sp-1: 0.25rem;
      --sp-2: 0.5rem;
      --sp-3: 0.75rem;
      --sp-4: 1rem;
      --sp-5: 1.25rem;
      --sp-6: 1.5rem;
      --sp-8: 2rem;
      --sp-10: 2.5rem;
      --sp-12: 3rem;
      --sp-16: 4rem;
      --sp-20: 5rem;
      --sp-24: 6rem;

      /* Typography */
      --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      --fs-xs: 0.75rem;
      --fs-sm: 0.875rem;
      --fs-base: 1rem;
      --fs-lg: 1.125rem;
      --fs-xl: 1.25rem;
      --fs-2xl: 1.5rem;
      --fs-3xl: 1.875rem;
      --fs-4xl: 2.25rem;
      --fs-5xl: 3rem;
      --fs-6xl: 3.75rem;

      /* Radius */
      --radius-sm: 0.25rem;
      --radius-md: 0.5rem;
      --radius-lg: 0.75rem;
      --radius-xl: 1rem;
      --radius-2xl: 1.5rem;

      /* Shadows */
      --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.05);
      --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.07), 0 2px 4px -2px oklch(0% 0 0 / 0.05);
      --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.04);
      --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.04);

      /* Transitions */
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 400ms ease;

      /* Layout */
      --max-width: 1200px;
      --header-height: 72px;
    }

    /* ============================================
       RESET & BASE
    ============================================ */
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
      -webkit-text-size-adjust: 100%;
    }

    body {
      font-family: var(--font-family);
      font-size: var(--fs-base);
      line-height: 1.6;
      color: var(--text-primary);
      background: var(--bg-primary);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    img {
      max-width: 100%;
      height: auto;
      display: block;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    ul, ol {
      list-style: none;
    }

    /* ============================================
       UTILITY
    ============================================ */
    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 var(--sp-6);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      white-space: nowrap;
      border: 0;
    }

    /* ============================================
       BUTTONS
    ============================================ */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: var(--sp-2);
      padding: var(--sp-3) var(--sp-6);
      font-size: var(--fs-sm);
      font-weight: 600;
      line-height: 1.5;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
      white-space: nowrap;
    }

    .btn-primary {
      background: var(--red-primary);
      color: var(--white);
    }
    .btn-primary:hover {
      background: var(--red-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: var(--navy);
      color: var(--white);
    }
    .btn-secondary:hover {
      background: var(--navy-light);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-outline {
      background: transparent;
      color: var(--white);
      border: 2px solid var(--white);
    }
    .btn-outline:hover {
      background: var(--white);
      color: var(--navy);
    }

    .btn-ghost {
      background: transparent;
      color: var(--navy);
      border: 2px solid var(--navy);
    }
    .btn-ghost:hover {
      background: var(--navy);
      color: var(--white);
    }

    .btn-lg {
      padding: var(--sp-4) var(--sp-8);
      font-size: var(--fs-lg);
      border-radius: var(--radius-lg);
    }

    /* ============================================
       HEADER
    ============================================ */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--white);
      border-bottom: 1px solid var(--border-color);
      height: var(--header-height);
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 100%;
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 var(--sp-6);
    }

    .header-logo {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
      font-weight: 800;
      font-size: var(--fs-lg);
      color: var(--navy);
      flex-shrink: 0;
    }

    .header-logo-icon {
      width: 36px;
      height: 36px;
      background: var(--red-primary);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: var(--fs-lg);
    }

    .header-nav {
      display: flex;
      align-items: center;
      gap: var(--sp-1);
    }

    .header-nav a {
      padding: var(--sp-2) var(--sp-3);
      font-size: var(--fs-sm);
      font-weight: 500;
      color: var(--text-secondary);
      border-radius: var(--radius-md);
      transition: color var(--transition-fast), background var(--transition-fast);
    }
    .header-nav a:hover {
      color: var(--navy);
      background: var(--bg-muted);
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: var(--sp-4);
    }

    .header-utility {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
      font-size: var(--fs-xs);
      color: var(--text-muted);
    }
    .header-utility a:hover {
      color: var(--navy);
    }

    .header-donate-btn {
      padding: var(--sp-2) var(--sp-5);
      font-size: var(--fs-sm);
    }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: var(--sp-2);
      cursor: pointer;
    }
    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--gray-700);
      border-radius: 2px;
      transition: all var(--transition-base);
    }
    .hamburger.active span:nth-child(1) {
      transform: rotate(45deg) translate(5px, 5px);
    }
    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }
    .hamburger.active span:nth-child(3) {
      transform: rotate(-45deg) translate(5px, -5px);
    }

    /* Mobile drawer */
    .mobile-drawer {
      display: none;
      position: fixed;
      top: var(--header-height);
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      padding: var(--sp-6);
      transform: translateX(100%);
      transition: transform var(--transition-slow);
      overflow-y: auto;
    }
    .mobile-drawer.open {
      transform: translateX(0);
    }
    .mobile-drawer a {
      display: block;
      padding: var(--sp-4) 0;
      font-size: var(--fs-lg);
      font-weight: 500;
      color: var(--text-primary);
      border-bottom: 1px solid var(--border-color);
    }
    .mobile-drawer .mobile-donate {
      margin-top: var(--sp-6);
      width: 100%;
      text-align: center;
    }

    /* ============================================
       HERO
    ============================================ */
    .hero {
      position: relative;
      background: linear-gradient(135deg, var(--navy) 0%, oklch(35% 0.1 245) 50%, oklch(45% 0.12 260) 100%);
      color: var(--white);
      overflow: hidden;
      padding: var(--sp-24) 0 var(--sp-20);
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse at 20% 80%, oklch(50% 0.18 18 / 0.15) 0%, transparent 50%),
        radial-gradient(ellipse at 80% 20%, oklch(60% 0.12 245 / 0.2) 0%, transparent 50%);
      pointer-events: none;
    }

    .hero-pattern {
      position: absolute;
      inset: 0;
      opacity: 0.04;
      background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 720px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: var(--sp-2);
      padding: var(--sp-2) var(--sp-4);
      background: oklch(100% 0 0 / 0.12);
      border: 1px solid oklch(100% 0 0 / 0.2);
      border-radius: var(--radius-2xl);
      font-size: var(--fs-sm);
      font-weight: 500;
      margin-bottom: var(--sp-6);
      backdrop-filter: blur(4px);
    }

    .hero-badge-dot {
      width: 8px;
      height: 8px;
      background: var(--red-primary);
      border-radius: 50%;
      animation: pulse-dot 2s ease-in-out infinite;
    }

    @keyframes pulse-dot {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .hero h1 {
      font-size: var(--fs-5xl);
      font-weight: 900;
      line-height: 1.1;
      letter-spacing: -0.02em;
      margin-bottom: var(--sp-6);
    }

    .hero p {
      font-size: var(--fs-lg);
      line-height: 1.7;
      opacity: 0.9;
      margin-bottom: var(--sp-8);
      max-width: 560px;
    }

    .hero-ctas {
      display: flex;
      gap: var(--sp-4);
      flex-wrap: wrap;
    }

    /* ============================================
       MISSION
    ============================================ */
    .mission {
      padding: var(--sp-20) 0;
      background: var(--bg-primary);
    }

    .mission-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-16);
      align-items: center;
    }

    .mission-label {
      font-size: var(--fs-sm);
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--red-primary);
      margin-bottom: var(--sp-3);
    }

    .mission h2 {
      font-size: var(--fs-3xl);
      font-weight: 800;
      color: var(--navy);
      line-height: 1.2;
      margin-bottom: var(--sp-6);
    }

    .mission-body {
      font-size: var(--fs-base);
      color: var(--text-secondary);
      line-height: 1.8;
    }

    .mission-body p + p {
      margin-top: var(--sp-4);
    }

    .mission-image {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--gray-200) 0%, var(--gray-300) 100%);
    }

    .mission-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, oklch(92% 0.02 245), oklch(88% 0.03 18));
      color: var(--gray-500);
      font-size: var(--fs-sm);
      text-align: center;
      padding: var(--sp-8);
    }

    .mission-image-placeholder svg {
      width: 64px;
      height: 64px;
      margin-bottom: var(--sp-4);
      opacity: 0.4;
    }

    /* ============================================
       IMPACT STATS
    ============================================ */
    .impact {
      padding: var(--sp-20) 0;
      background: linear-gradient(135deg, var(--navy) 0%, oklch(35% 0.1 245) 100%);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .impact::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 80% 50%, oklch(50% 0.18 18 / 0.1) 0%, transparent 50%);
      pointer-events: none;
    }

    .impact-header {
      text-align: center;
      margin-bottom: var(--sp-16);
      position: relative;
      z-index: 1;
    }

    .impact-label {
      font-size: var(--fs-sm);
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: oklch(80% 0.05 18);
      margin-bottom: var(--sp-3);
    }

    .impact h2 {
      font-size: var(--fs-3xl);
      font-weight: 800;
    }

    .impact-stats {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--sp-8);
      position: relative;
      z-index: 1;
    }

    .impact-stat {
      text-align: center;
      padding: var(--sp-8) var(--sp-4);
      background: oklch(100% 0 0 / 0.06);
      border: 1px solid oklch(100% 0 0 / 0.1);
      border-radius: var(--radius-xl);
      backdrop-filter: blur(4px);
      transition: transform var(--transition-base), background var(--transition-base);
    }
    .impact-stat:hover {
      transform: translateY(-4px);
      background: oklch(100% 0 0 / 0.1);
    }

    .impact-number {
      font-size: var(--fs-5xl);
      font-weight: 900;
      line-height: 1;
      margin-bottom: var(--sp-2);
      color: var(--white);
    }

    .impact-number .counter-prefix {
      font-size: var(--fs-3xl);
    }

    .impact-unit {
      font-size: var(--fs-lg);
      font-weight: 600;
      opacity: 0.9;
      margin-bottom: var(--sp-2);
    }

    .impact-desc {
      font-size: var(--fs-sm);
      opacity: 0.7;
      line-height: 1.5;
    }

    .impact-footnote {
      text-align: center;
      margin-top: var(--sp-12);
      font-size: var(--fs-sm);
      opacity: 0.6;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
      position: relative;
      z-index: 1;
    }

    /* ============================================
       PROGRAMS ACCORDION
    ============================================ */
    .programs {
      padding: var(--sp-20) 0;
      background: var(--bg-surface);
    }

    .section-header {
      text-align: center;
      margin-bottom: var(--sp-12);
    }

    .section-label {
      font-size: var(--fs-sm);
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--red-primary);
      margin-bottom: var(--sp-3);
    }

    .section-header h2 {
      font-size: var(--fs-3xl);
      font-weight: 800;
      color: var(--navy);
    }

    .accordion {
      max-width: 800px;
      margin: 0 auto;
    }

    .accordion-item {
      background: var(--white);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-lg);
      margin-bottom: var(--sp-3);
      overflow: hidden;
      transition: box-shadow var(--transition-base);
    }
    .accordion-item:hover {
      box-shadow: var(--shadow-md);
    }

    .accordion-trigger {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: var(--sp-5) var(--sp-6);
      font-size: var(--fs-lg);
      font-weight: 600;
      color: var(--navy);
      text-align: left;
      transition: background var(--transition-fast);
    }
    .accordion-trigger:hover {
      background: var(--bg-muted);
    }

    .accordion-trigger-left {
      display: flex;
      align-items: center;
      gap: var(--sp-4);
    }

    .accordion-icon-circle {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: var(--fs-lg);
      flex-shrink: 0;
    }
    .accordion-icon-circle.red { background: var(--red-surface); }
    .accordion-icon-circle.navy { background: var(--navy-surface); }

    .accordion-chevron {
      width: 20px;
      height: 20px;
      color: var(--gray-400);
      transition: transform var(--transition-base);
      flex-shrink: 0;
    }
    .accordion-item.active .accordion-chevron {
      transform: rotate(180deg);
    }

    .accordion-panel {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-slow), padding var(--transition-slow);
    }
    .accordion-item.active .accordion-panel {
      max-height: 300px;
    }

    .accordion-panel-inner {
      padding: 0 var(--sp-6) var(--sp-6);
      padding-left: calc(40px + var(--sp-4) + var(--sp-6));
      color: var(--text-secondary);
      line-height: 1.7;
      font-size: var(--fs-base);
    }

    /* ============================================
       GET INVOLVED
    ============================================ */
    .involved {
      padding: var(--sp-20) 0;
      background: var(--bg-primary);
    }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--sp-8);
    }

    .involved-card {
      padding: var(--sp-8);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-xl);
      transition: transform var(--transition-base), box-shadow var(--transition-base);
      background: var(--white);
    }
    .involved-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .involved-card-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: var(--sp-5);
      font-size: var(--fs-2xl);
    }
    .involved-card-icon.red { background: var(--red-surface); }
    .involved-card-icon.navy { background: var(--navy-surface); }

    .involved-card h3 {
      font-size: var(--fs-xl);
      font-weight: 700;
      color: var(--navy);
      margin-bottom: var(--sp-3);
    }

    .involved-card p {
      font-size: var(--fs-base);
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: var(--sp-6);
    }

    .involved-card .btn {
      width: 100%;
    }

    /* ============================================
       NEWS CAROUSEL
    ============================================ */
    .news {
      padding: var(--sp-20) 0;
      background: var(--bg-surface);
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: var(--sp-10);
    }

    .news-nav {
      display: flex;
      gap: var(--sp-2);
    }

    .news-nav-btn {
      width: 44px;
      height: 44px;
      border-radius: var(--radius-md);
      border: 1px solid var(--border-color);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      background: var(--white);
      transition: all var(--transition-fast);
    }
    .news-nav-btn:hover {
      background: var(--navy);
      color: var(--white);
      border-color: var(--navy);
    }

    .news-track-wrapper {
      overflow: hidden;
    }

    .news-track {
      display: flex;
      gap: var(--sp-6);
      transition: transform var(--transition-slow);
    }

    .news-card {
      min-width: calc(50% - var(--sp-3));
      flex-shrink: 0;
      background: var(--white);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: transform var(--transition-base), box-shadow var(--transition-base);
    }
    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .news-card-image {
      height: 180px;
      background: linear-gradient(135deg, var(--gray-200), var(--gray-300));
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: var(--fs-sm);
    }

    .news-card-body {
      padding: var(--sp-6);
    }

    .news-card-tag {
      display: inline-block;
      padding: var(--sp-1) var(--sp-3);
      background: var(--red-surface);
      color: var(--red-primary);
      font-size: var(--fs-xs);
      font-weight: 600;
      border-radius: var(--radius-sm);
      margin-bottom: var(--sp-3);
    }

    .news-card h3 {
      font-size: var(--fs-lg);
      font-weight: 700;
      color: var(--navy);
      margin-bottom: var(--sp-3);
      line-height: 1.3;
    }

    .news-card p {
      font-size: var(--fs-sm);
      color: var(--text-secondary);
      line-height: 1.7;
    }

    /* ============================================
       DONATE CTA
    ============================================ */
    .donate-cta {
      padding: var(--sp-20) 0;
      background: var(--bg-primary);
    }

    .donate-cta-inner {
      background: linear-gradient(135deg, var(--red-primary) 0%, oklch(55% 0.2 10) 100%);
      border-radius: var(--radius-2xl);
      padding: var(--sp-16);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .donate-cta-inner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 80% 20%, oklch(100% 0 0 / 0.08) 0%, transparent 50%);
      pointer-events: none;
    }

    .donate-cta-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: var(--sp-12);
      position: relative;
      z-index: 1;
    }

    .donate-cta-content h2 {
      font-size: var(--fs-4xl);
      font-weight: 900;
      margin-bottom: var(--sp-4);
    }

    .donate-cta-content p {
      font-size: var(--fs-lg);
      opacity: 0.9;
      line-height: 1.7;
      margin-bottom: var(--sp-6);
    }

    .donate-cta-trust {
      font-size: var(--fs-sm);
      opacity: 0.8;
    }

    .impact-table {
      width: 100%;
      border-collapse: separate;
      border-spacing: 0;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: oklch(100% 0 0 / 0.1);
      backdrop-filter: blur(4px);
    }

    .impact-table th {
      text-align: left;
      padding: var(--sp-3) var(--sp-4);
      font-size: var(--fs-sm);
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      background: oklch(100% 0 0 / 0.1);
    }

    .impact-table td {
      padding: var(--sp-3) var(--sp-4);
      font-size: var(--fs-sm);
      border-top: 1px solid oklch(100% 0 0 / 0.1);
    }

    .impact-table td:first-child {
      font-weight: 700;
      white-space: nowrap;
    }

    /* ============================================
       FOOTER
    ============================================ */
    .footer {
      background: var(--gray-900);
      color: oklch(90% 0.005 245);
      padding: var(--sp-16) 0 var(--sp-8);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: var(--sp-10);
      margin-bottom: var(--sp-12);
    }

    .footer-brand {
      max-width: 280px;
    }

    .footer-brand-logo {
      display: flex;
      align-items: center;
      gap: var(--sp-3);
      font-weight: 800;
      font-size: var(--fs-lg);
      color: var(--white);
      margin-bottom: var(--sp-4);
    }

    .footer-brand-icon {
      width: 32px;
      height: 32px;
      background: var(--red-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: var(--fs-base);
    }

    .footer-brand p {
      font-size: var(--fs-sm);
      line-height: 1.7;
      opacity: 0.6;
    }

    .footer-col h4 {
      font-size: var(--fs-sm);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--white);
      margin-bottom: var(--sp-4);
    }

    .footer-col a {
      display: block;
      padding: var(--sp-1) 0;
      font-size: var(--fs-sm);
      opacity: 0.6;
      transition: opacity var(--transition-fast);
    }
    .footer-col a:hover {
      opacity: 1;
    }

    .footer-bottom {
      border-top: 1px solid oklch(100% 0 0 / 0.1);
      padding-top: var(--sp-8);
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: var(--sp-4);
    }

    .footer-copy {
      font-size: var(--fs-xs);
      opacity: 0.5;
    }

    .footer-social {
      display: flex;
      gap: var(--sp-4);
    }

    .footer-social a {
      font-size: var(--fs-sm);
      opacity: 0.5;
      transition: opacity var(--transition-fast);
    }
    .footer-social a:hover {
      opacity: 1;
    }

    /* ============================================
       DONATION MODAL
    ============================================ */
    .modal-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: oklch(0% 0 0 / 0.5);
      z-index: 200;
      align-items: center;
      justify-content: center;
      padding: var(--sp-6);
      backdrop-filter: blur(4px);
    }
    .modal-overlay.active {
      display: flex;
    }

    .modal {
      background: var(--white);
      border-radius: var(--radius-2xl);
      max-width: 520px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: var(--shadow-xl);
      animation: modal-enter 0.3s ease;
    }

    @keyframes modal-enter {
      from {
        opacity: 0;
        transform: translateY(20px) scale(0.96);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: var(--sp-6) var(--sp-8);
      border-bottom: 1px solid var(--border-color);
    }

    .modal-header h2 {
      font-size: var(--fs-xl);
      font-weight: 700;
      color: var(--navy);
    }

    .modal-close {
      width: 36px;
      height: 36px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-500);
      transition: background var(--transition-fast), color var(--transition-fast);
    }
    .modal-close:hover {
      background: var(--bg-muted);
      color: var(--gray-700);
    }

    .modal-body {
      padding: var(--sp-8);
    }

    .donate-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--sp-3);
      margin-bottom: var(--sp-6);
    }

    .donate-amount-btn {
      padding: var(--sp-4) var(--sp-2);
      border: 2px solid var(--border-color);
      border-radius: var(--radius-lg);
      text-align: center;
      font-weight: 600;
      color: var(--navy);
      background: var(--white);
      transition: all var(--transition-fast);
      cursor: pointer;
    }
    .donate-amount-btn:hover {
      border-color: var(--red-primary);
      color: var(--red-primary);
    }
    .donate-amount-btn.selected {
      background: var(--red-primary);
      border-color: var(--red-primary);
      color: var(--white);
    }

    .donate-amount-btn .amount {
      display: block;
      font-size: var(--fs-xl);
      font-weight: 800;
    }

    .donate-amount-btn .amount-impact {
      display: block;
      font-size: var(--fs-xs);
      opacity: 0.7;
      margin-top: var(--sp-1);
      font-weight: 400;
    }

    .donate-custom {
      margin-bottom: var(--sp-6);
    }

    .donate-custom label {
      display: block;
      font-size: var(--fs-sm);
      font-weight: 600;
      color: var(--text-secondary);
      margin-bottom: var(--sp-2);
    }

    .donate-custom-input {
      width: 100%;
      padding: var(--sp-3) var(--sp-4);
      border: 2px solid var(--border-color);
      border-radius: var(--radius-lg);
      font-size: var(--fs-lg);
      font-weight: 600;
      font-family: var(--font-family);
      color: var(--navy);
      transition: border-color var(--transition-fast);
    }
    .donate-custom-input:focus {
      outline: none;
      border-color: var(--red-primary);
    }
    .donate-custom-input::placeholder {
      color: var(--gray-300);
    }

    .donate-frequency {
      display: flex;
      gap: var(--sp-3);
      margin-bottom: var(--sp-6);
    }

    .freq-btn {
      flex: 1;
      padding: var(--sp-3);
      border: 2px solid var(--border-color);
      border-radius: var(--radius-md);
      text-align: center;
      font-size: var(--fs-sm);
      font-weight: 600;
      color: var(--text-secondary);
      background: var(--white);
      cursor: pointer;
      transition: all var(--transition-fast);
    }
    .freq-btn:hover {
      border-color: var(--red-primary);
      color: var(--red-primary);
    }
    .freq-btn.selected {
      background: var(--red-surface);
      border-color: var(--red-primary);
      color: var(--red-primary);
    }

    .donate-submit {
      width: 100%;
      padding: var(--sp-4);
      font-size: var(--fs-lg);
    }

    .donate-secure {
      text-align: center;
      margin-top: var(--sp-4);
      font-size: var(--fs-xs);
      color: var(--text-muted);
    }

    /* ============================================
       RESPONSIVE
    ============================================ */
    @media (max-width: 1024px) {
      .hero h1 {
        font-size: var(--fs-4xl);
      }

      .impact-stats {
        grid-template-columns: repeat(2, 1fr);
      }

      .donate-cta-grid {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: 2fr 1fr 1fr;
      }
    }

    @media (max-width: 768px) {
      :root {
        --header-height: 64px;
      }

      .header-nav,
      .header-utility {
        display: none;
      }

      .hamburger {
        display: flex;
      }

      .mobile-drawer {
        display: block;
      }

      .hero {
        padding: var(--sp-16) 0 var(--sp-12);
      }

      .hero h1 {
        font-size: var(--fs-3xl);
      }

      .hero p {
        font-size: var(--fs-base);
      }

      .hero-ctas {
        flex-direction: column;
      }

      .hero-ctas .btn {
        width: 100%;
      }

      .mission-grid {
        grid-template-columns: 1fr;
        gap: var(--sp-8);
      }

      .impact-stats {
        grid-template-columns: repeat(2, 1fr);
        gap: var(--sp-4);
      }

      .impact-number {
        font-size: var(--fs-3xl);
      }

      .involved-grid {
        grid-template-columns: 1fr;
      }

      .news-card {
        min-width: 100%;
      }

      .donate-cta-inner {
        padding: var(--sp-8);
      }

      .donate-cta-content h2 {
        font-size: var(--fs-2xl);
      }

      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }

      .footer-brand {
        grid-column: span 2;
      }

      .section-header h2 {
        font-size: var(--fs-2xl);
      }

      .donate-amounts {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 480px) {
      .impact-stats {
        grid-template-columns: 1fr;
      }

      .impact-number {
        font-size: var(--fs-4xl);
      }

      .impact-table {
        font-size: var(--fs-xs);
      }

      .impact-table th,
      .impact-table td {
        padding: var(--sp-2) var(--sp-3);
      }

      .footer-grid {
        grid-template-columns: 1fr;
      }

      .footer-brand {
        grid-column: span 1;
      }
    }
  </style>
</head>
<body>

  <!-- ========== HEADER ========== -->
  <header class="header" role="banner">
    <div class="header-inner">
      <a href="#" class="header-logo" aria-label="Global Aid Alliance Home">
        <div class="header-logo-icon" aria-hidden="true">+</div>
        Global Aid Alliance
      </a>

      <nav class="header-nav" aria-label="Main navigation">
        <a href="#mission">About Us</a>
        <a href="#programs">Disaster Relief</a>
        <a href="#programs">Programs &amp; Services</a>
        <a href="#involved">Volunteer</a>
        <a href="#involved">Find Local Chapter</a>
      </nav>

      <div class="header-actions">
        <div class="header-utility">
          <a href="#">Sign In</a>
          <a href="#">Contact Us</a>
          <a href="#">Espa&ntilde;ol</a>
        </div>
        <button class="btn btn-primary header-donate-btn" onclick="openDonateModal()" aria-label="Donate Now">Donate</button>
        <button class="hamburger" id="hamburger" aria-label="Toggle menu" aria-expanded="false">
          <span></span>
          <span></span>
          <span></span>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile drawer -->
  <div class="mobile-drawer" id="mobileDrawer" role="dialog" aria-label="Mobile navigation">
    <a href="#mission" onclick="closeMobileMenu()">About Us</a>
    <a href="#programs" onclick="closeMobileMenu()">Disaster Relief</a>
    <a href="#programs" onclick="closeMobileMenu()">Programs &amp; Services</a>
    <a href="#involved" onclick="closeMobileMenu()">Volunteer</a>
    <a href="#involved" onclick="closeMobileMenu()">Find Local Chapter</a>
    <button class="btn btn-primary btn-lg mobile-donate" onclick="closeMobileMenu(); openDonateModal()">Donate Now</button>
  </div>

  <!-- ========== HERO ========== -->
  <section class="hero" aria-label="Hero">
    <div class="hero-pattern"></div>
    <div class="container">
      <div class="hero-content">
        <div class="hero-badge">
          <span class="hero-badge-dot"></span>
          Active disaster response underway
        </div>
        <h1>When Disaster Strikes, We're There</h1>
        <p>From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
        <div class="hero-ctas">
          <button class="btn btn-primary btn-lg" onclick="openDonateModal()">Donate Now</button>
          <a href="#involved" class="btn btn-outline btn-lg">Become a Volunteer</a>
        </div>
      </div>
    </div>
  </section>

  <!-- ========== MISSION ========== -->
  <section class="mission" id="mission" aria-label="Our Mission">
    <div class="container">
      <div class="mission-grid">
        <div class="mission-text">
          <div class="mission-label">Our Mission</div>
          <h2>Preventing and Alleviating Human Suffering in the Face of Emergencies</h2>
          <div class="mission-body">
            <p>Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.</p>
            <p>We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most — regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.</p>
          </div>
        </div>
        <div class="mission-image" role="img" aria-label="Relief workers providing aid to a community">
          <div class="mission-image-placeholder">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M18 18.72a9.094 9.094 0 003.741-.479 3 3 0 00-4.682-2.72m.94 3.198l.001.031c0 .225-.012.447-.037.666A11.944 11.944 0 0112 21c-2.17 0-4.207-.576-5.963-1.584A6.062 6.062 0 016 18.719m12 0a5.971 5.971 0 00-.941-3.197m0 0A5.995 5.995 0 0012 12.75a5.995 5.995 0 00-5.058 2.772m0 0a3 3 0 00-4.681 2.72 8.986 8.986 0 003.74.477m.94-3.197a5.971 5.971 0 00-.94 3.197M15 6.75a3 3 0 11-6 0 3 3 0 016 0zm6 3a2.25 2.25 0 11-4.5 0 2.25 2.25 0 014.5 0zm-13.5 0a2.25 2.25 0 11-4.5 0 2.25 2.25 0 014.5 0z" />
            </svg>
            Relief workers providing community aid
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ========== IMPACT STATS ========== -->
  <section class="impact" id="impact" aria-label="Our Impact">
    <div class="container">
      <div class="impact-header">
        <div class="impact-label">Our Impact</div>
        <h2>Real Lives Changed, Real Communities Strengthened</h2>
      </div>
      <div class="impact-stats">
        <div class="impact-stat">
          <div class="impact-number"><span class="counter-prefix" data-target="12" data-suffix="M">0</span></div>
          <div class="impact-unit">people assisted</div>
          <div class="impact-desc">annually across all programs</div>
        </div>
        <div class="impact-stat">
          <div class="impact-number"><span class="counter-prefix" data-target="50" data-suffix="K">0</span></div>
          <div class="impact-unit">active volunteers</div>
          <div class="impact-desc">in our global network</div>
        </div>
        <div class="impact-stat">
          <div class="impact-number"><span class="counter-prefix" data-target="190" data-suffix="">0</span></div>
          <div class="impact-unit">countries</div>
          <div class="impact-desc">where we've provided aid</div>
        </div>
        <div class="impact-stat">
          <div class="impact-number"><span class="counter-prefix" data-target="850" data-prefix="$" data-suffix="M">0</span></div>
          <div class="impact-unit">raised</div>
          <div class="impact-desc">in the last fiscal year</div>
        </div>
      </div>
      <p class="impact-footnote">These figures represent real lives changed — families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.</p>
    </div>
  </section>

  <!-- ========== PROGRAMS ========== -->
  <section class="programs" id="programs" aria-label="Programs and Services">
    <div class="container">
      <div class="section-header">
        <div class="section-label">Programs &amp; Services</div>
        <h2>How We Serve Communities Worldwide</h2>
      </div>
      <div class="accordion">
        <!-- Disaster Relief -->
        <div class="accordion-item">
          <button class="accordion-trigger" aria-expanded="false" onclick="toggleAccordion(this)">
            <span class="accordion-trigger-left">
              <span class="accordion-icon-circle red" aria-hidden="true">&#x1F3D4;</span>
              Disaster Relief
            </span>
            <svg class="accordion-chevron" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M19 9l-7 7-7-7"/></svg>
          </button>
          <div class="accordion-panel">
            <div class="accordion-panel-inner">
              Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.
            </div>
          </div>
        </div>
        <!-- Blood Donation -->
        <div class="accordion-item">
          <button class="accordion-trigger" aria-expanded="false" onclick="toggleAccordion(this)">
